WITH department_totals AS (SELECT dept_id, SUM(CASE WHEN job_title = 'Director' THEN salary ELSE 0 END) AS director_salary FROM employees WHERE hire_date BETWEEN '2023-05-02' AND '2024-07-01' GROUP BY dept_id) SELECT departments.id, departments.budget, departments.dept_name, department_totals.director_salary FROM departments LEFT JOIN department_totals ON departments.id = department_totals.dept_id WHERE department_totals.director_salary >= 77
